229		// 下限が無い回では、前の回までの下限未満の指摘を足さない (record-schema.md の「下限未満の指摘の参照」)。
230		// 足すと、下限を指定していないのに、下限未満の指摘が採択になる。
231		if fd.Origin == "prior_below_minimum" && doc.Runs[ri].MinFixNecessity == "" {
232			add("回に下限 (min_fix_necessity) が無いのに、origin が prior_below_minimum の指摘があります (下限が無い回では、前の回までの下限未満の指摘を足さない)")
233		}
234		ref := fd.BelowMinimumRef
235		if ref == nil {
236			if fd.Origin == "prior_below_minimum" {
237				add("origin が prior_below_minimum なのに below_minimum_ref がありません (足した指摘は、前の回のどの指摘かを書く)")
238			}
239			return problems
240		}
241		target, msg := belowMinimumRefTarget(doc, ri, ref)
242		if msg != "" {
243			add("%s", msg)
244		}
245		switch ref.LineCheck {
246		case "holds", "not-holds", "unverifiable":
247		default:
248			add("below_minimum_ref.line_check は holds / not-holds / unverifiable のいずれか: %q", ref.LineCheck)
249		}
250		if ref.LineReason == "" {
251			add("below_minimum_ref.line_reason がありません (対象の行が変わっていないかの結果の理由)")
252		}
253		if !judgmentOmitted(fd) {
254			return problems
255		}
256		if fd.Verdict == "below_minimum" && fd.PlanRef != nil {
257			add("判定を省略した下限未満の指摘 (B2) には plan_ref を書かない (一緒に直したことは、必要度を判定した参照先の指摘に書く)")
258		}
259		// 判定を省略した指摘 (A3・B2)。分類・被害者・帰結・根拠の検証・ゲート・必要度は書かない。
260		// 書いてあると、参照先の値と、この指摘の値のどちらを読むのかが決まらない。
261		for _, kv := range []struct {
262			key     string
263			written bool
264		}{
265			{"category", fd.Category != ""},
266			{"audience", fd.Audience != ""},
267			{"audience_initial", fd.AudienceInitial != ""},
268			{"consequence", fd.Consequence != recordConsequence{}},
269			{"premise_check", fd.PremiseCheck != recordPremise{}},
270			{"gates_fired", len(fd.GatesFired) > 0},
271			{"prior_defect", fd.PriorDefect != nil},
272			{"fix_necessity", fd.FixNecessity != ""},
273			{"fix_necessity_reason", fd.FixNecessityReason != nil},
274		} {
275			if kv.written {
276				add("判定を省略した指摘 (below_minimum_ref.line_check が holds) では %s を書かない (参照先の指摘のものを読む)", kv.key)
277			}
278		}
279		if target == nil {
280			return problems
281		}
282		// D12: 参照先の必要度が、この回の下限以上なら採択 (A3)、満たなければ下限未満 (B2)。
283		want := "adopted"
284		if fixNecessityBelow(target.FixNecessity, doc.Runs[ri].MinFixNecessity) {
285			want = "below_minimum"
286		}
287		if fd.Verdict != want {
288			minimum := doc.Runs[ri].MinFixNecessity
289			if minimum == "" {
290				minimum = "無し"
291			}
292			add("判定を省略した指摘の verdict は、参照先の必要度 %s と回の下限 %s から %s に決まりますが、%q です",
293				target.FixNecessity, minimum, want, fd.Verdict)
294		}
295		return problems
296	}
297	
298	// recordPriorBelowMinimumProblems は、回 (添字 ri) に足すべき下限未満の指摘が、足されているかを
299	// 検査する。それより前の回の、残っている下限未満の指摘 (必要度を判定して下限未満にした指摘で、
300	// この回より前の回の指摘が参照して、判定し直しても採択にしてもいないもの) のうち、必要度がこの回の
301	// 下限以上のものは、この回の指摘として足す (record-schema.md の「下限未満の指摘の参照」)。
302	// 足し忘れると、下限を下げても、その指摘は採択にならず直されないまま残る。下限が無い回では足さない
303	// (下限を指定せずにループを起動し直しただけで、下限未満の指摘が採択にならないようにするため) ので、何も求めない。
304	// 足したかどうかは、この回の指摘の below_minimum_ref が参照しているかで見る。呼び出し元は、
305	// 記録の最後の回についてだけ呼ぶ。
306	func recordPriorBelowMinimumProblems(doc *recordDoc, ri int) []string {
307		referenced := map[[2]int]bool{}
308		for _, fd := range doc.Runs[ri].Findings {
309			if ref := fd.BelowMinimumRef; ref != nil {
310				referenced[[2]int{ref.Run, ref.Finding}] = true
311			}
312		}
313		minimum := doc.Runs[ri].MinFixNecessity
314		// 下限が無い回では足さない。下限が列挙に無い値のときは、比べられないので報告しない
315		// (列挙の誤りは別に報告する)。
316		if fixNecessityRank(minimum) == 0 {
317			return nil
318		}
319		var problems []string
320		for _, e := range belowMinimumEntries(doc, ri) {
321			necessity := e.finding.FixNecessity
322			if e.resolved || referenced[[2]int{e.run, e.finding.ID}] || fixNecessityBelow(necessity, minimum) {
323				continue
324			}
325			problems = append(problems, fmt.Sprintf(
326				"残っている下限未満の指摘 (%d 回目の id %d。必要度 %s) が、この回の下限 %s 以上なのに、この回の findings に足されていません (origin: prior_below_minimum と below_minimum_ref を書いて足す)",
327				e.run, e.finding.ID, necessity, minimum))
328		}
329		return problems
330	}
331	
332	// findingFixNecessity は指摘の必要度を返す。判定を省略した指摘は、参照先の必要度。
333	// 分からなければ空。
334	func findingFixNecessity(doc *recordDoc, ri int, fd recordFinding) string {
335		if !judgmentOmitted(fd) {
336			return fd.FixNecessity
337		}
338		if target, _ := belowMinimumRefTarget(doc, ri, fd.BelowMinimumRef); target != nil {
339			return target.FixNecessity
340		}
341		return ""
342	}
343	
344	// renderFixNecessityCounts は推移の表の必要度の 3 列 (Must・Should・Could) を返す。
345	// 判定に関わらず、その回で必要度が分かる指摘を数える。fix_necessity_reason を必須にする回
346	// (recordFixNecessityFirstRun) より前の回 (必須にする回が無い記録ではすべての回) は「—」にする。0 と書くと、
347	// 必要度を判定して 0 件だったように読めるため。
348	func renderFixNecessityCounts(doc *recordDoc, ri, firstRun int) []string {
349		if firstRun < 0 || ri < firstRun {
350			return []string{"—", "—", "—"}
351		}
352		counts := map[string]int{}
353		for _, fd := range doc.Runs[ri].Findings {
354			counts[findingFixNecessity(doc, ri, fd)]++
355		}
356		return []string{
357			fmt.Sprint(counts["must"]), fmt.Sprint(counts["should"]), fmt.Sprint(counts["could"]),
358		}
359	}
360	
361	// belowMinimumEntry は、節「下限未満の指摘」の 1 行になる指摘 (必要度を判定して下限未満に
362	// した指摘)。resolved は、後の回の指摘が参照して、判定し直したか採択 (A3) にしたか、
363	// 採択した問題と一緒に直した (plan_ref の問題が直った) こと。
364	// reported は、同じ問題がまた報告されて判定を省略した指摘 (B2) の位置。
365	type belowMinimumEntry struct {
366		run      int
367		finding  recordFinding
368		resolved bool
369		reported []string
370	}
371	
372	// belowMinimumEntries は、記録の最初の n 回の中の、必要度を判定して下限未満にした指摘を、記録の順に返す。
373	// 足し忘れの検査と節「下限未満の指摘」の両方が、これで「残っている」を決める。別々に決めると、
374	// 片方だけを変えたときに、検査と生成サマリの結果が一致しなくなる。
375	func belowMinimumEntries(doc *recordDoc, n int) []*belowMinimumEntry {
376		var entries []*belowMinimumEntry
377		index := map[[2]int]*belowMinimumEntry{}
378		for ri, run := range doc.Runs[:n] {
379			for _, fd := range run.Findings {
380				if ref := fd.BelowMinimumRef; ref != nil {
381					if e := index[[2]int{ref.Run, ref.Finding}]; e != nil {
382						if judgmentOmitted(fd) && fd.Verdict == "below_minimum" {
383							e.reported = append(e.reported, fmt.Sprintf("%d 回目 #%d", ri+1, fd.ID))
384						} else {
385							e.resolved = true
386						}
387					}
388				}
389				if fd.Verdict == "below_minimum" && fixNecessityRank(fd.FixNecessity) > 0 {
390					e := &belowMinimumEntry{run: ri + 1, finding: fd, resolved: planRefFixed(doc, fd.PlanRef)}
391					entries = append(entries, e)
392					index[[2]int{ri + 1, fd.ID}] = e
393				}
394			}
395		}
396		return entries
397	}
398	
399	// planRefFixed は、plan_ref の問題が直ったか (状態が done か done-external か) を返す。問題がまだ
400	// 直っていないか、直さないと決めた (not-fixed) なら、指摘の箇所も直っていない。参照の実在は別に検査する。
401	func planRefFixed(doc *recordDoc, ref *recordPlanRef) bool {
402		if ref == nil || ref.Run < 1 || ref.Run > len(doc.Runs) {
403			return false
404		}
405		for _, pl := range doc.Runs[ref.Run-1].Plans {
406			if pl.ProblemID == ref.Problem {
407				return pl.Status == "done" || pl.Status == "done-external"
408			}
409		}
410		return false
411	}
412	
413	// renderBelowMinimumSection は節「下限未満の指摘」を書く。記録に下限未満の指摘が 1 件も
414	// 無ければ何も書かない。並べるのは残っている指摘だけで、必要度ごとの表にする。
415	// 件数はここで数え、人が書いた集計をどこからも読まない (推移の表と同じ)。
416	func renderBelowMinimumSection(b *strings.Builder, doc *recordDoc) {
417		hasBelowMinimum := false
418		for _, run := range doc.Runs {
419			for _, fd := range run.Findings {
420				if fd.Verdict == "below_minimum" {
421					hasBelowMinimum = true
422				}
423			}
424		}
425		if !hasBelowMinimum {
426			return
427		}
428		b.WriteString("\n## 下限未満の指摘\n")
429		entries := belowMinimumEntries(doc, len(doc.Runs))
430		remaining := 0
431		for _, necessity := range []string{"must", "should", "could"} {
432			var rows []*belowMinimumEntry
433			for _, e := range entries {
434				if !e.resolved && e.finding.FixNecessity == necessity {
435					rows = append(rows, e)
436				}
437			}
438			if len(rows) == 0 {
439				continue
440			}
441			remaining += len(rows)
442			fmt.Fprintf(b, "\n### %s (%d 件)\n\n", fixNecessityJa(necessity), len(rows))
443			b.WriteString("| 判定した回 | 指摘 | 回避策 | また報告された回 |\n")
444			b.WriteString("| --- | --- | --- | --- |\n")
445			for _, e := range rows {
446				b.WriteString(recordRow(renderBelowMinimumCells(e)))
447			}
448		}
449		if remaining == 0 {
450			b.WriteString("\n残っている下限未満の指摘はありません (後の回で判定し直したか、採択にしたか、採択した問題と一緒に直した)。\n")
451		}
452	}
