454	// renderBelowMinimumCells は節「下限未満の指摘」の 1 行のセルのスライスを返す。
455	func renderBelowMinimumCells(e *belowMinimumEntry) []string {
456		fd := e.finding
457		loc := fd.File
458		if fd.Line > 0 {
459			loc = fmt.Sprintf("%s:%d", fd.File, fd.Line)
460		}
461		// 回避策は、条件 2 を判定した指摘 (Should) だけが持つ。条件 1 が成り立つ指摘 (Could) は
462		// 何もしなくても目的を達成できるので、回避策を書かない。
463		workaround := "—"
464		if r := fd.FixNecessityReason; r != nil && r.WorkaroundReason != "" {

535			add("runs がありません (実行が 1 つも無い)")
536		}
537		// 回ごとの問題 id の索引 (plan_ref の解決と被覆の検査に使う)。
538		plansByRun := make([]map[string]bool, len(doc.Runs))
539		for ri, run := range doc.Runs {
540			plansByRun[ri] = map[string]bool{}
541			for _, pl := range run.Plans {
542				plansByRun[ri][pl.ProblemID] = true
543			}
544		}
545		priorDefectFirstRun := recordPriorDefectFirstRun(doc.Runs)
546		fixNecessityFirstRun := recordFixNecessityFirstRun(doc.Runs)
547		decisionFirstRun := recordDecisionFirstRun(doc.Runs)
548		for ri, run := range doc.Runs {
549			rn := fmt.Sprintf("runs[%d] (%s %s)", ri, run.Date, run.Skill)
550			if !recordDateRe.MatchString(run.Date) {
551				add("%s: date が YYYY-MM-DD ではありません: %q", rn, run.Date)
552			}
553			if run.Skill == "" {
554				add("%s: skill がありません", rn)
555			}
556			if run.Model == "" {
557				add("%s: model がありません (レビューを実行したモデルを必ず残す)", rn)
558			}
559			if run.Scope != "incremental" && run.Scope != "full" {
560				add("%s: scope は incremental / full のいずれか: %q", rn, run.Scope)
561			}
562			if run.Head == "" {
563				add("%s: head がありません (レビュー時点の短縮 SHA)", rn)
564			}
565			if run.MinFixNecessity != "" && fixNecessityRank(run.MinFixNecessity) == 0 {
566				add("%s: min_fix_necessity は must / should / could のいずれか (下限が無い回では書かない): %q", rn, run.MinFixNecessity)
567			}
568	
569			priorDefectRequired := priorDefectFirstRun >= 0 && ri >= priorDefectFirstRun
570			fixNecessityRequired := fixNecessityFirstRun >= 0 && ri >= fixNecessityFirstRun
571			verdictByID := map[int]string{}
572			for fi, fd := range run.Findings {
573				fn := fmt.Sprintf("%s: findings[%d] (id %d)", rn, fi, fd.ID)
574				if fd.ID <= 0 {
575					add("%s: id は正の整数にする", fn)
576				} else if _, dup := verdictByID[fd.ID]; dup {
577					add("%s: id が同じ回の中で重複しています", fn)
578				}
579				verdictByID[fd.ID] = fd.Verdict
580				for _, kv := range []struct{ key, val string }{
581					{"file", fd.File}, {"summary", fd.Summary},
582				} {
583					if kv.val == "" {
584						add("%s: %s がありません", fn, kv.key)
585					}
586				}
587				switch fd.Verdict {
588				case "adopted", "held", "rejected", "below_minimum":
589				default:
590					add("%s: verdict は adopted / held / rejected / below_minimum のいずれか: %q", fn, fd.Verdict)
591				}
592				if fd.VerdictReason == "" {
593					add("%s: verdict_reason がありません (判定の経路をノード ID で書く)", fn)
594				}
595				// 指摘の出所。省略時は上流のレビュー (review)。residual はループ中に自己採択したもの
596				// (record-schema.md「ループ中に記録の外で直さない」)。prior_below_minimum は、前の回までの
597				// 下限未満の指摘を、この回の指摘として足したもの (同「下限未満の指摘の参照」)。
598				switch fd.Origin {
599				case "", "review", "residual", "prior_below_minimum":
600				default:
601					add("%s: origin は review / residual / prior_below_minimum のいずれか (省略時は review): %q", fn, fd.Origin)
602				}
603				if fd.PlanRef != nil {
604					if fd.PlanRef.Run < 1 || fd.PlanRef.Run > len(doc.Runs) {
605						add("%s: plan_ref の run %d は存在しません (回は 1〜%d)", fn, fd.PlanRef.Run, len(doc.Runs))
606					} else if !plansByRun[fd.PlanRef.Run-1][fd.PlanRef.Problem] {
607						add("%s: plan_ref の問題 %q は %d 回目の plans にありません", fn, fd.PlanRef.Problem, fd.PlanRef.Run)
608					}
609				}
610				for _, m := range recordBelowMinimumRefProblems(doc, ri, fd) {
611					add("%s: %s", fn, m)
612				}
613				// D9 で当たって判定を省略した指摘 (A3・B2) は、分類・被害者・帰結・根拠の検証・
614				// ゲート・必要度を書かない。書かないことは recordBelowMinimumRefProblems が検査する。
615				if judgmentOmitted(fd) {
616					continue
617				}
618				for _, kv := range []struct{ key, val string }{
619					{"category", fd.Category}, {"audience", fd.Audience},
620				} {
621					if kv.val == "" {
622						add("%s: %s がありません", fn, kv.key)
623					}
624				}
625				// audience の列挙。列挙外の値をエラーにせずに通すと D7 (被害者の判定) の入力が壊れる。
626				if fd.Audience != "" && !recordAudiences[fd.Audience] {
627					add("%s: audience は operator / admin / provider / developer のいずれか: %q", fn, fd.Audience)
628				}
629				if fd.AudienceInitial != "" && !recordAudiences[fd.AudienceInitial] {
630					add("%s: audience_initial は operator / admin / provider / developer のいずれか: %q", fn, fd.AudienceInitial)
631				}
632				for _, kv := range []struct{ key, val string }{
633					{"condition", fd.Consequence.Condition}, {"who", fd.Consequence.Who},
634					{"what", fd.Consequence.What}, {"detectability", fd.Consequence.Detectability},
635				} {
636					if kv.val == "" {
637						add("%s: consequence.%s がありません (帰結の 4 項目は必須)", fn, kv.key)
638					}
639				}
640				switch fd.PremiseCheck.Stages {
641				case "none", "A", "A+B":
642				default:
643					add("%s: premise_check.stages は none / A / A+B のいずれか: %q", fn, fd.PremiseCheck.Stages)
644				}
645				switch fd.PremiseCheck.Result {
646				case "verified", "wrong", "unverifiable", "skipped":
647				default:
648					add("%s: premise_check.result は verified / wrong / unverifiable / skipped のいずれか: %q",
649						fn, fd.PremiseCheck.Result)
650				}
651				if (fd.PremiseCheck.Stages == "none") != (fd.PremiseCheck.Result == "skipped") {
652					add("%s: stages が none のときだけ result は skipped (stages %q / result %q)",
653						fn, fd.PremiseCheck.Stages, fd.PremiseCheck.Result)
654				}
655				for _, m := range recordPriorDefectProblems(priorDefectRequired, fd) {
656					add("%s: %s", fn, m)
657				}
658				for _, m := range recordFixNecessityProblems(fixNecessityRequired, run.MinFixNecessity, fd) {
659					add("%s: %s", fn, m)
660				}
661			}
662	
663			// 足すはずの下限未満の指摘は、最後の回についてだけ検査する。前の回の findings は後から
664			// 書き換えない (record-schema.md の「スキーマ」) ので、報告しても直せない。足し忘れは、
665			// その回を書いた直後の検査 (その回が最後の回のとき) で報告される。
666			if ri == len(doc.Runs)-1 {
667				for _, m := range recordPriorBelowMinimumProblems(doc, ri) {
668					add("%s: %s", rn, m)
669				}
670			}
671	
672			problemIDs := map[string]bool{}
673			for _, pl := range run.Plans {
674				if pl.ProblemID != "" && problemIDs[pl.ProblemID] {
675					add("%s: problem_id %q が重複しています", rn, pl.ProblemID)
676				}
677				problemIDs[pl.ProblemID] = true
678			}
679			for pi, pl := range run.Plans {
680				pn := fmt.Sprintf("%s: plans[%d] (%s)", rn, pi, pl.ProblemID)
681				for _, kv := range []struct{ key, val string }{
682					{"problem_id", pl.ProblemID}, {"cause", pl.Cause},
683				} {
684					if kv.val == "" {
685						add("%s: %s がありません", pn, kv.key)
686					}
687				}
688				if len(pl.FindingIDs) == 0 {
689					add("%s: finding_ids がありません (1 つ以上)", pn)
690				}
691				for _, id := range pl.FindingIDs {
692					v, ok := verdictByID[id]
693					if !ok {
694						add("%s: finding_ids の %d は同じ回の findings にありません", pn, id)
695					} else if v != "adopted" {
696						add("%s: finding_ids の %d は採択 (adopted) ではありません (verdict %s)。修正計画は採択だけを束ねる", pn, id, v)
697					}
698				}
699				// externalOnly は done-external 専用のキーが空であることを検査する。
700				// スキーマ表が「done-external のときだけ書く」と定める排他で、書かせる
701				// だけで検査しないと、done でコミット済みなのに外部 URL が残る記録が
702				// エラーにならずに通る (sha の排他は前から検査されていた)。列挙外の status では
703				// 呼ばない。default が列挙違反を報告するので、そこへ重ねると 1 つの
704				// 誤字が 2 つの問題になるため。
705				externalOnly := func() {
706					for _, kv := range []struct{ key, val string }{
707						{"applied_external_url", pl.AppliedExternalURL}, {"notes", pl.Notes},
708					} {
709						if kv.val != "" {
710							add("%s: status %s なのに %s %q があります。%s は status done-external 専用",
711								pn, pl.Status, kv.key, kv.val, kv.key)
712						}
713					}
714				}
715				// approachRequired は修正方法 (approach) が無いことを報告する。必須かどうかは
716				// status ごとに決まる (スキーマ表の approach の行)。修正に進む状態
717				// (pending) と修正を終えた状態 (done / done-external) では必須、awaiting-human
718				// では任意 (人間の立案待ちは approach を持たず、人間の回答の後に書く)、
719				// investigated では逆に書いてあれば報告する。
720				approachRequired := func() {
721					if pl.Approach == "" {
722						add("%s: approach がありません", pn)
723					}
724				}
725				// noSHAYet はまだ修正していない状態 (investigated / pending / awaiting-human) の
726				// 共通の検査で、done-external 専用のキーが無く、sha も無いことを確認する。
727				noSHAYet := func() {
728					externalOnly()
729					if pl.SHA != "" {
730						add("%s: status %s なのに sha %q があります。直したのなら status: done にする", pn, pl.Status, pl.SHA)
731					}
732				}
733				switch pl.Status {
734				case "investigated":
735					// 調査フェーズの結果だけを持つ状態。修正方法と順序は立案フェーズが書いて
736					// pending / awaiting-human に進める。ここに書いてあると、立案フェーズが書いたのか
737					// 調査フェーズが立案フェーズの中身まで書いたのかを記録から読めなくなるので、書いてあれば報告する。
738					noSHAYet()
739					// 調査 (investigation) は他の状態では任意だが、この状態では必須。
740					// 無いことは「未調査」を意味する (スキーマ表) ので、調査済みの状態と矛盾する。
741					// 通してしまうと、立案フェーズが未調査の問題に立案し、同じ原因の別の現れが残る。
742					// 中身 (scope) の検査は下の inv != nil の検査に委ねる。
743					if pl.Investigation == nil {
744						add("%s: 調査済み (investigated) には investigation (調べた範囲と結果) が必須。"+
745							"無いものは未調査で、状態と矛盾する。調べたなら scope を書き、まだなら plans に載せない", pn)
746					}
747					if pl.Approach != "" {
748						add("%s: 調査済み (investigated) では approach を書かない。修正方法を決めたのなら status: pending にする", pn)
749					}
750					if pl.Order != 0 {
751						add("%s: 調査済み (investigated) では order を書かない。順序を決めたのなら status: pending にする", pn)
752					}
753				case "pending", "awaiting-human":
754					noSHAYet()
755					if pl.Status == "pending" {
756						approachRequired()
757					}
758					if pl.Status == "awaiting-human" && pl.Options == "" {
759						add("%s: status awaiting-human には options (選択肢とトレードオフ) が必須", pn)
760					}
761				case "done":
762					externalOnly()
763					approachRequired()
764					if pl.SHA == "" {
765						add("%s: status done には sha (短縮 SHA) が必須。リポジトリ外の成果物への反映で"+
766							"コミットが立たないなら status: done-external にする", pn)
767					}
768				case "done-external":
769					approachRequired()
770					// コミットが無いのだから sha を書けるはずがない。書けているなら
771					// リポジトリ内の修正なので done が正しい。
772					if pl.SHA != "" {
773						add("%s: status done-external なのに sha %q があります。コミットがあるなら status: done にする", pn, pl.SHA)
774					}
775					if pl.AppliedExternalURL == "" && pl.Notes == "" {
776						add("%s: status done-external には applied_external_url (反映先の URL) か "+
777							"notes (反映先と、反映を確認した方法) のどちらかが必須", pn)
778					}
779				case "not-fixed":
780					// 今回は直さないと人間が決めた問題。コミットも外部への反映も無い。
781					noSHAYet()
782				default:
783					add("%s: status は investigated / pending / awaiting-human / done / done-external / not-fixed のいずれか: %q", pn, pl.Status)
784				}
785				for _, m := range recordDecisionProblems(decisionFirstRun >= 0 && ri >= decisionFirstRun, pl) {
786					add("%s: %s", pn, m)
787				}
788				// 調査は investigated 以外の状態では任意 (無ければ未調査) だが、書くなら範囲 (scope) が要る。
789				// 範囲の無い調査は「どこまで調べたか」を残さず、未調査と区別できない。
790				if inv := pl.Investigation; inv != nil {
791					if strings.TrimSpace(inv.Scope) == "" {
792						add("%s: investigation.scope がありません (調べた範囲。実行したコマンドと目で読んだ対象を書く)。範囲を書かない調査は未調査と区別できない", pn)
793					}
794					for _, kv := range []struct {
795						key  string
796						vals []string
797					}{{"included", inv.Included}, {"excluded", inv.Excluded}} {
798						for i, v := range kv.vals {
799							if strings.TrimSpace(v) == "" {
800								add("%s: investigation.%s[%d] が空です (箇所を書くか要素を消す)", pn, kv.key, i)
801							}
802						}
803					}
804				}
805				// doc-dag の確認 (doc_dag) は任意だが、書くなら対象 (scope) と結果 (result) が要る。
806				// 片方だけの記録は、何を確認して何が分かったかを残さない。
807				if dd := pl.DocDag; dd != nil {
808					if strings.TrimSpace(dd.Scope) == "" {
809						add("%s: doc_dag.scope がありません (doc-dag に渡した対象の文書群)", pn)
810					}
811					if strings.TrimSpace(dd.Result) == "" {
812						add("%s: doc_dag.result がありません (どちらが SSOT か決まっていない重複・参照の循環の有無と対処)", pn)
813					}
814				}
815				// 検証 (verification) は任意だが、書くなら再確認した範囲 (near_edges) が要る。
816				// 範囲の無い検証は、読んだつもりの記録と読んでいない記録を区別できない。
817				if ver := pl.Verification; ver != nil {
818					if len(ver.NearEdges) == 0 {
819						add("%s: verification.near_edges がありません (観点 B で再確認した範囲。nearedges の出力から写す)", pn)
820					}
821					for i, v := range ver.NearEdges {
822						if strings.TrimSpace(v) == "" {
823							add("%s: verification.near_edges[%d] が空です (範囲を書くか要素を消す)", pn, i)
824						}
825					}
826				}
827				for _, d := range pl.DependsOn {
828					if d == pl.ProblemID {
829						add("%s: depends_on が自己参照しています", pn)
830						continue
831					}
832					if !problemIDs[d] {
833						add("%s: depends_on の %q は同じ回の plans にありません", pn, d)
834					}
835				}
836			}
837			// 被覆: 採択は自回の plans か plan_ref で覆われる。覆われない採択は、
838			// 対処しないまま、誰にも知らされずに消える。
839			//
840			// 免除するのは「plans がまだ無い最後の回」だけで、これは fix 前の状態を指す。
841			// 後続の回が追記された時点でその回はもう fix 前ではないので、免除を解く。
842			// 全回で len(run.Plans) > 0 を条件にしていた頃は、plans を書かないまま
843			// 次の回に進んだ過去の回の採択が、検査からも review-triage-fix (最後の回の
844			// findings しか見ない) からも見えなくなり、誰にも知らされずに消えていた。
845			isLastRun := ri == len(doc.Runs)-1
846			if len(run.Plans) > 0 || !isLastRun {
847				covered := map[int]bool{}
848				for _, pl := range run.Plans {
849					for _, id := range pl.FindingIDs {
850						covered[id] = true
851					}
852				}
853				for _, fd := range run.Findings {
854					if fd.Verdict != "adopted" || covered[fd.ID] {
855						continue
856					}
857					if fd.PlanRef != nil {
858						continue // 参照自体の実在は上の finding ループで検査済み
859					}
860					add("%s: findings id %d: 採択が修正計画に載っていません (自回の plans にも plan_ref にも無い)", rn, fd.ID)
861				}
862			}
863			for _, cycle := range recordDependsOnCycles(run.Plans) {
864				add("%s: depends_on が循環しています (%s)。順序が定まらない。同じ原因の 1 問題に束ねるべきものを分けていないかを疑う",
865					rn, strings.Join(cycle, " → "))
866			}
867		}
868		return problems
869	}
870	
871	// recordDependsOnCycles は plans の depends_on の循環を検出する。自己参照は
872	// 個別に報告するのでここでは扱わない。同じ循環は 1 度だけ返す。
873	func recordDependsOnCycles(plans []recordPlan) [][]string {
874		deps := make(map[string][]string, len(plans))

